<?php
/** Phase 8 — revision history controls. Uses native WordPress revisions only. */
if (!defined('ABSPATH')) exit;
if (!class_exists('BSW_Phase8_Revision_History')) {
final class BSW_Phase8_Revision_History {
 public static function init(){
  add_action('add_meta_boxes_wiki_article',array(__CLASS__,'box'));
  add_shortcode('bsw_article_history',array(__CLASS__,'shortcode'));
  add_action('admin_post_bsw_p8_restore_revision',array(__CLASS__,'restore'));
  add_action('admin_post_bsw_p8_compare_revision',array(__CLASS__,'compare'));
 }
 public static function box(){ add_meta_box('bsw_p8_history','BIGSHOR Revision History',array(__CLASS__,'render_box'),'wiki_article','side','default'); }
 public static function render_box($post){ $revs=wp_get_post_revisions($post->ID,array('posts_per_page'=>12,'orderby'=>'date','order'=>'DESC')); echo '<p>WordPress keeps the saved revision record. Select a revision to compare or restore it.</p>'; if(!$revs){echo '<p>No saved revisions yet.</p>';return;} echo '<ol class="bsw-p8-list">'; foreach($revs as $r){$u=get_userdata($r->post_author); echo '<li><strong>'.esc_html(get_date_from_gmt($r->post_modified_gmt,get_option('date_format').' '.get_option('time_format'))).'</strong><br>'.esc_html($u?$u->display_name:'Unknown').'<br><a href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=bsw_p8_compare_revision&post_id='.$post->ID.'&revision_id='.$r->ID),'bsw_p8_compare_'.$post->ID)).'">Compare with current</a>'; if(current_user_can('edit_post',$post->ID)) echo ' · <a href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=bsw_p8_restore_revision&post_id='.$post->ID.'&revision_id='.$r->ID),'bsw_p8_restore_'.$post->ID)).'" onclick="return confirm(\'Restore this revision as a new saved version?\')">Restore</a>'; echo '</li>'; } echo '</ol>'; }
 public static function shortcode($atts){$a=shortcode_atts(array('id'=>get_the_ID(),'limit'=>20),$atts,'bsw_article_history');$id=absint($a['id']);$p=get_post($id);if(!$p||$p->post_type!=='wiki_article')return '';if(!current_user_can('read_post',$id))return '<p>History is unavailable.</p>';$revs=wp_get_post_revisions($id,array('posts_per_page'=>max(1,min(100,absint($a['limit'])))));$o='<section class="bsw-p8-history"><h2>Revision history</h2>';if(!$revs)return $o.'<p>No saved revisions yet.</p></section>';$o.='<ol>';foreach($revs as $r){$u=get_userdata($r->post_author);$o.='<li><strong>'.esc_html(get_date_from_gmt($r->post_modified_gmt,get_option('date_format').' '.get_option('time_format'))).'</strong> — '.esc_html($u?$u->display_name:'Unknown contributor').' — '.esc_html(wp_trim_words(wp_strip_all_tags($r->post_content),18)).'</li>';}$o.='</ol></section>';return $o;}
 public static function compare(){ $id=absint($_GET['post_id']??0);$rid=absint($_GET['revision_id']??0);if(!$id||!$rid||!wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce']??'')),'bsw_p8_compare_'.$id)||!current_user_can('edit_post',$id))wp_die('Permission or security check failed.',403);$r=wp_get_post_revision($rid);if(!$r||$r->post_parent!==$id)wp_die('Revision does not belong to this article.',404);$p=get_post($id);require_once ABSPATH.'wp-admin/includes/revision.php';$diff=wp_text_diff($r->post_content,$p->post_content,array('title'=>'Revision comparison'));wp_die('<div class="wrap"><h1>BIGSHOR revision comparison</h1><p>'.esc_html(get_the_title($id)).'</p>'.($diff?:'<p>No content differences detected.</p>').'<p><a href="'.esc_url(get_edit_post_link($id)).'">Return to article</a></p></div>','Revision comparison',array('response'=>200)); }
 public static function restore(){ require_once ABSPATH.'wp-admin/includes/revision.php'; $id=absint($_GET['post_id']??0);$rid=absint($_GET['revision_id']??0);if(!$id||!$rid||!wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce']??'')),'bsw_p8_restore_'.$id)||!current_user_can('edit_post',$id))wp_die('Permission or security check failed.',403);$r=wp_get_post_revision($rid);$p=get_post($id);if(!$r||!$p||$p->post_type!=='wiki_article'||$r->post_parent!==$id)wp_die('Revision does not belong to this article.',404);$result=wp_restore_post_revision($rid);if(is_wp_error($result))wp_die(esc_html($result->get_error_message()),500);wp_safe_redirect(add_query_arg('bsw_revision_restored','1',get_edit_post_link($id,'url')));exit; }
}
BSW_Phase8_Revision_History::init();
}
